+						},
+						provider: {
+							id: adapter.name,
+							durationMs: performance.now() - startedAt,
+						},
+					};
+				}
+				const provider: CapabilityProvider = {
+					id: adapter.name,
+					durationMs: performance.now() - startedAt,
+				};
+				return { ok: true, data: output.data, provider };
+			} catch (error) {
+				return toCapabilityFailure(error, performance.now() - startedAt);
+			}
+		},
+	};
+}

