--- packages/inngest/src/functions/notification-notifier.ts	
+++ packages/inngest/src/functions/notification-notifier.ts	
@@ -0,0 +1,82 @@
+import { env } from "@aevryn/env/server";
+import { WorkflowService } from "@aevryn/workflow";
+import { z } from "zod";
+import { inngest } from "../client";
+import { notificationPublishEvent } from "../events";
+
+const workflowService = new WorkflowService();
+
+const publishEventSchema = z.object({
+	event: z.object({
+		data: z.object({
+			notificationId: z.string().min(1),
+		}),
+	}),
+});
+
+export async function publishNotification(data: unknown): Promise<{
+	notificationId: string;
+	outcome: "delivered" | "skipped" | "not-found";
+}> {
+	const result = publishEventSchema.safeParse(data).success
+		? publishEventSchema.parse(data).event.data
+		: null;
+	if (!result) {
+		return { notificationId: "unknown", outcome: "skipped" };
+	}
+	const { notificationId } = result;
+
+	const notification = await workflowService.getNotification(notificationId);
+	if (!notification) {
+		return { notificationId, outcome: "not-found" };
+	}
+	if (notification.deliveredAt) {
+		return { notificationId, outcome: "delivered" };
+	}
+	if (notification.channel !== "webhook") {
+		return { notificationId, outcome: "skipped" };
+	}
+	const url = notification.body?.url;
+	if (typeof url !== "string" || !/^https?:\/\//i.test(url)) {
+		return { notificationId, outcome: "skipped" };
+	}
+	try {
+		const response = await fetch(url, {
+			method: "POST",
+			headers: {
+				"content-type": "application/json",
+			},
+			body: JSON.stringify({
+				event: "aevryn:notification",
+				subject: notification.subject,
+				body: notification.body,
+				workflowId: notification.workflowId,
+				sentAt: new Date().toISOString(),
+				baseUrl: env.WEBHOOK_BASE_URL,
+			}),
+			signal: AbortSignal.timeout(15_000),
+		});
+		if (!response.ok) {
+			throw new Error(`webhook responded ${response.status}`);
+		}
+		await workflowService.markNotificationDelivered(notificationId);
+		return { notificationId, outcome: "delivered" };
+	} catch {
+		// Leave deliveredAt unset; the next publish attempt retries the POST.
+		return { notificationId, outcome: "skipped" };
+	}
+}
+
+export const notificationNotifier = inngest.createFunction(
+	{
+		id: "notification-notifier",
+		retries: 5,
+		triggers: [{ event: notificationPublishEvent }],
+	},
+	async ({ event, step }) => {
+		const publish = await step.run("publish-notification", () =>
+			publishNotification(event.data),
+		);
+		return publish;
+	},
+);

Index: packages/inngest/src/functions/schedule-tick.ts
===================================================================
--- packages/inngest/src/functions/schedule-tick.ts	
+++ packages/inngest/src/functions/schedule-tick.ts	
@@ -0,0 +1,143 @@
+import { computeNextRun, WorkflowService } from "@aevryn/workflow";
+import { NonRetriableError } from "inngest";
+
+import { inngest } from "../client";
+import { executionRunEvent } from "../events";
+
+const workflowService = new WorkflowService();
+
+interface FireOutcome {
+	scheduleId: string;
+	executionId?: string;
+	skipped?: string;
+}
+
+interface WakeOutcome {
+	executionId: string;
+	nextExecutionId?: string;
+	skipped?: string;
+}
+
+export const scheduleTick = inngest.createFunction(
+	{
+		id: "schedule-tick",
+		retries: 2,
+	},
+	async ({ step }) => {
+		const now = new Date();
+		const due = await step.run("find-due-work", async () => {
+			return {
+				schedules: await workflowService.listDueSchedules(now),
+				sleeping: await workflowService.listDueSleepingExecutions(now),
+			};
+		});
+
+		const fired: FireOutcome[] = [];
+		for (const schedule of due.schedules) {
+			const outcome = await step.run("fire-schedule", async () => {
+				const workflow = await workflowService.getWorkflowById(
+					schedule.workflowId,
+				);
+				if (!workflow) {
+					throw new NonRetriableError(
+						`Schedule ${schedule.id} references missing workflow`,
+					);
+				}
+				if (
+					workflow.status === "cancelled" ||
+					workflow.status === "failed" ||
+					workflow.status === "completed" ||
+					workflow.status === "paused"
+				) {
+					if (workflow.status !== "paused") {
+						await workflowService.setScheduleEnabled(schedule.id, false);
+					}
+					return {
+						scheduleId: schedule.id,
+						skipped: `workflow ${workflow.status}`,
+					} satisfies FireOutcome;
+				}
+				const config = (schedule.config ?? {}) as {
+					prompt?: string;
+				};
+				const prompt = config.prompt ?? workflow.objective;
+				const { execution } = await workflowService.enqueueMessage(
+					workflow.id,
+					prompt,
+				);
+				await inngest.send({
+					name: executionRunEvent,
+					data: {
+						workflowId: workflow.id,
+						executionId: execution.id,
+						prompt,
+					},
+				});
+				const nextRunAt = computeNextRun(
+					schedule.cron ?? undefined,
+					schedule.intervalSeconds ?? undefined,
+				);
+				await workflowService.markScheduleRan(schedule.id, nextRunAt);
+				await workflowService.createNotification({
+					userId: workflow.userId,
+					workflowId: workflow.id,
+					channel: "in-app",
+					type: "schedule.started",
+					subject: "Scheduled run started",
+					body: { prompt },
+				});
+				return {
+					scheduleId: schedule.id,
+					executionId: execution.id,
+				} satisfies FireOutcome;
+			});
+			fired.push(outcome);
+		}
+
+		const woken: WakeOutcome[] = [];
+		for (const execution of due.sleeping) {
+			const outcome = await step.run("wake-sleeping", async () => {
+				const workflow = await workflowService.getWorkflowById(
+					execution.workflowId,
+				);
+				if (!workflow) {
+					return {
+						executionId: execution.id,
+						skipped: "workflow unavailable",
+					} satisfies WakeOutcome;
+				}
+				if (workflow.status === "paused") {
+					return {
+						executionId: execution.id,
+						skipped: "workflow paused",
+					} satisfies WakeOutcome;
+				}
+				const prompt =
+					execution.prompt.length > 0 ? execution.prompt : workflow.objective;
+				const { execution: nextExecution } =
+					await workflowService.enqueueMessage(workflow.id, prompt);
+				await inngest.send({
+					name: executionRunEvent,
+					data: {
+						workflowId: workflow.id,
+						executionId: nextExecution.id,
+						prompt,
+					},
+				});
+				await workflowService.completeSupersededExecution(execution.id);
+				return {
+					executionId: execution.id,
+					nextExecutionId: nextExecution.id,
+				} satisfies WakeOutcome;
+			});
+			woken.push(outcome);
+		}
+
+		return {
+			firedSchedules: fired.length,
+			wokenExecutions: woken.length,
+			fired,
+			woken,
+		};
+	},
+);

