+	> {
+		const workflows = await this.workflows.listByUser(userId, limit);
+		return Promise.all(
+			workflows.map(async (workflow) => {
+				const executions = await this.executions.listByWorkflow(workflow.id, 1);
+				return { workflow, execution: executions[0] ?? null };
+			}),
